import objc
from Cocoa import NSObject, NSURL, NSArray, NSData

class ShazamKitWrapper(NSObject):
    def init(self):
        self = super().init()
        if not self.setup_shazam():
            raise Exception('Failed to setup Shazam')
        return self

    def setup_shazam(self):
        self.shazam = objc.lookUpClass('ShazamKit').shared()
        if not self.shazam:
            return False
        self.recognizer = self.shazam.recognizer()
        return True

    @objc.python_method
    def recognize_song_from_file(self, file_path):
        url = NSURL.fileURLWithPath_(file_path)
        data = NSData.alloc().initWithContentsOfURL_(url)
        self.recognizer.recognizeData_completion_(data, self.on_recognize_completion)

    @objc.python_method
    def on_recognize_completion(self, response, error):
        if error:
            print('Error:', error)
            return
        print('Recognized songs:', [str(song) for song in response.topSongs()])

if __name__ == '__main__':
    import sys
    app = NSObject.alloc().init()
    with objc.autorelease_pool(app):
        wrapper = ShazamKitWrapper.alloc().init()
        wrapper.recognize_song_from_file(sys.argv[1])

