import collectd
import requests
import json

SUMO_LOGIC_URL = "https://api.sumologic.com/api/v1/collector/messages"
COLLECTOR_TOKEN = "YOUR_COLLECTOR_TOKEN"

def configure(conf):
    for node in conf.children:
        key = node.key.lower()
        val = node.values[0]
        if key == 'sumologic_url':
            global SUMO_LOGIC_URL
            SUMO_LOGIC_URL = val
        elif key == 'collector_token':
            global COLLECTOR_TOKEN
            COLLECTOR_TOKEN = val
        else:
            collectd.warning('Unknown config key: %s.' % key)

def dispatch_values(values, plugin_instance):
    data = {
        "timestamp": int(collectd.time() * 1000),
        "values": [v for v in values],
        "plugin": "python",
        "plugin_instance": plugin_instance,
        "type": "gauge",
        "type_instance": plugin_instance,
    }
    headers = {
        "Content-Type": "application/json",
        "X-Sumo-Token": COLLECTOR_TOKEN
    }
    try:
        response = requests.post(SUMO_LOGIC_URL, data=json.dumps(data), headers=headers)
        if response.status_code != 200:
            collectd.warning('Failed to send data to Sumo Logic: %s.' % response.text)
    except Exception as e:
        collectd.warning('Failed to send data to Sumo Logic: %s.' % str(e))

def write(data=None, type=None, type_instance=None, plugin=None, plugin_instance=None, values=None):
    dispatch_values(values, plugin_instance)

collectd.register_config(configure)
collectd.register_write(write)

