import collectd
import json
import urllib.request

SUMO_LOGIC_URL = 'https://api.sumologic.com/receiver/v1/messages'

def configure(conf):
    for node in conf.children:
        key = node.key.lower()
        val = node.values[0]
        if key == 'sumo_logic_url':
            global SUMO_LOGIC_URL
            SUMO_LOGIC_URL = val
        else:
            collectd.warning('Unknown config key: %s.' % key)

def dispatch_values(values, identifier, metric_name, timestamp):
    payload = {
        'time': timestamp,
        'metric': metric_name,
        'value': values,
        'source': identifier,
    }
    headers = {
        'Content-Type': 'application/json',
        'X-Sumo-Name': identifier,
        'X-Sumo-Category': 'collectd',
    }
    req = urllib.request.Request(SUMO_LOGIC_URL, json.dumps(payload).encode(), headers)
    urllib.request.urlopen(req)

def read(data=None):
    for plugin in collectd.get_list():
        if not plugin.values:
            continue
        identifier = "%s-%s" % (plugin.plugin, plugin.type)
        dispatch_values(plugin.values, identifier, plugin.type, plugin.time)

collectd.register_config(configure)
collectd.register_read(read)

