import numpy as np

class HEIFManager:
    def __init__(self, file_path):
        self.file_path = file_path
        self.heif_file = libheif.open_heif(file_path)

    def read_heif(self):
        image = self.heif_file.get_primary_image()
        width, height = image.get_width(), image.get_height()
        data = np.frombuffer(image.get_raw_image(), np.uint8).reshape((height, width, 3))
        return data

    def write_heif(self, data, file_path=None):
        if file_path is None:
            file_path = self.file_path
        image = libheif.Image()
        image.create(data.shape[1], data.shape[0], 1)
        image.set_raw_image(data.tobytes())
        libheif.write_heif(file_path, [image])

    def get_metadata(self):
        return self.heif_file.get_metadata()

    def set_metadata(self, metadata):
        self.heif_file.set_metadata(metadata)

