class SalesforceCLI:
    def __init__(self, username, password, security_token):
        self.sf = Salesforce(username=username, password=password, security_token=security_token)

    def create_package(self, name):
        # Create a new package
        package = self.sf.Package.create({'Name': name})
        return package['id']

    def add_metadata_to_package(self, package_id, metadata_types):
        # Add metadata types to the package
        for metadata_type in metadata_types:
            self.sf.Package.PackageType.create(metadata_type, package_id)

    def retrieve_metadata(self, metadata_types, output_dir):
        # Retrieve metadata types and save them to the output directory
        for metadata_type in metadata_types:
            metadata = self.sf.metadata.get(metadata_type)
            with open(f'{output_dir}/{metadata_type}.xml', 'w') as f:
                f.write(metadata)

    def deploy_to_production(self, package_id):
        # Deploy the package to production
        deploy_response = self.sf.Package.install(package_id, 'Production')
        return deploy_response


