import openjpeg
import numpy as np
from PIL import Image

class OpenJPEG:
    def __init__(self, file):
        self.file = file

    def read_image(self):
        with open(self.file, 'rb') as f:
            jp2 = f.read()
        data = openjpeg.PyDecoder().decode(jp2)
        return Image.fromarray(np.array(data))

    def write_image(self, image, format='jpeg'):
        image_data = np.array(image)
        jp2 = openjpeg.PyEncoder().encode(image_data)
        with open('output.' + format, 'wb') as f:
            f.write(jp2)

    def get_metadata(self):
        with open(self.file, 'rb') as f:
            jp2 = f.read()
        return openjpeg.get_info(jp2)

    def convert_format(self, format):
        image = self.read_image()
        return image.save('output.' + format)

